const getRoutePage=()=>{const path=window.location.pathname.replace(/\/+$/,'')||'/';if(/^\/proposals?\/.+/.test(path))return 'proposal-public';if(path==='/sat-proposal')return 'proposal';if(path==='/contact')return 'contact';if(path==='/portal'||new URLSearchParams(window.location.search).get('portal')==='1')return 'portal';if(path==='/admin')return 'admin';if(path==='/start-project')return 'wizard';return 'home'};
