 const testIntegrations=async()=>{setIntegrationBusy(true);setIntegrationNotice('');const {data,error}=await db.functions.invoke('proposal-notifications',{body:{action:'test'}});if(error)setIntegrationNotice(error.message||'Could not run integration test.');else{setIntegrationTest(data?.results||{});setIntegrationNotice('Test completed. Review the delivery results below.')}setIntegrationBusy(false)};
 const [pricingGroup,setPricingGroup]=useState('all');
 const [pricingSearch,setPricingSearch]=useState('');
 const [cp,setCp]=useState({client_name:'',client_email:'',project_name:'',project_type:'Website design & development',package_name:'Not selected',project_status:'Discovery',progress:0,next_step:'',project_brief:'',target_date:'',password:''});
 const [cpMsg,setCpMsg]=useState(''),[cpBusy,setCpBusy]=useState(false),[createdClient,setCreatedClient]=useState(null),[copiedClient,setCopiedClient]=useState(false),[projects,setProjects]=useState([]),[feedback,setFeedback]=useState([]),[proposalResponses,setProposalResponses]=useState([]),[selected,setSelected]=useState(null),[projectFiles,setProjectFiles]=useState([]),[activity,setActivity]=useState({title:'',description:''}),[approval,setApproval]=useState({title:'',description:'',file_id:''}),[upload,setUpload]=useState(null),[adminMsg,setAdminMsg]=useState(''),[actionBusy,setActionBusy]=useState(false),[projectInvoices,setProjectInvoices]=useState([]),[projectPayments,setProjectPayments]=useState([]),[invoiceDraft,setInvoiceDraft]=useState({title:'50% upfront deposit',amount:'',description:'',due_date:''});
 const upd=(k,v)=>setCp(x=>({...x,[k]:v}));
 const refresh=async()=>{if(!db)return;const [p,f,r]=await Promise.all([db.from('client_projects').select('*').order('created_at',{ascending:false}),db.from('client_project_feedback').select('*,client_projects(project_name,client_name)').order('created_at',{ascending:false}),db.from('client_proposal_responses').select('*,client_proposals(business_name,project_title)').order('created_at',{ascending:false})]);if(!p.error)setProjects(p.data||[]);if(!f.error)setFeedback(f.data||[]);if(!r.error)setProposalResponses(r.data||[])};
 useEffect(()=>{if(admin)refresh()},[admin,db]);
 useEffect(()=>{if(!selected||!db)return;Promise.all([db.from('client_project_files').select('*').eq('project_id',selected.id).order('created_at',{ascending:false}),db.from('client_project_invoices').select('*').eq('project_id',selected.id).order('created_at',{ascending:false}),db.from('client_project_payments').select('*').eq('project_id',selected.id).order('created_at',{ascending:false})]).then(([f,i,p])=>{setProjectFiles(f.data||[]);setProjectInvoices(i.data||[]);setProjectPayments(p.data||[])})},[selected?.id,db]);
 const createCp=async e=>{e.preventDefault();setCpBusy(true);setCpMsg('');setCreatedClient(null);setCopiedClient(false);if(String(cp.password||'').length<12){setCpMsg('Set a password with at least 12 characters.');setCpBusy(false);return}try{const {data,error}=await db.functions.invoke('create-client-project',{body:{...cp,client_email:cp.client_email.trim().toLowerCase(),progress:Number(cp.progress)}});if(error||data?.error){setCpMsg(data?.error||error?.message||'Could not create client project.')}else{setCreatedClient({name:cp.client_name,email:cp.client_email.trim().toLowerCase(),password:cp.password,project:cp.project_name});setCpMsg('Client account and project workspace created. No invitation email was sent.');setCp({client_name:'',client_email:'',project_name:'',project_type:'Website design & development',package_name:'Not selected',project_status:'Discovery',progress:0,next_step:'',project_brief:'',target_date:'',password:''});await refresh()}}catch(err){setCpMsg(err?.message||'Could not create client account.')}finally{setCpBusy(false)}};
 const updateProject=async()=>{if(!selected)return;setActionBusy(true);const {error}=await db.from('client_projects').update({project_status:selected.project_status,progress:Number(selected.progress),next_step:selected.next_step,target_date:selected.target_date||null,project_brief:selected.project_brief}).eq('id',selected.id);if(error)setAdminMsg('Could not update project: '+error.message);else{await db.from('client_project_updates').insert({project_id:selected.id,title:'Project progress updated',description:'Stage: '+selected.project_status+' · Progress: '+Number(selected.progress)+'%'+(selected.next_step?' · Next step: '+selected.next_step:''),update_type:'milestone',is_complete:selected.project_status==='Completed'});setAdminMsg('Project details saved and timeline updated.')}await refresh();setActionBusy(false)};
 const postActivity=async e=>{e.preventDefault();if(!selected)return;setActionBusy(true);const {error}=await db.from('client_project_updates').insert({project_id:selected.id,title:activity.title.trim(),description:activity.description.trim(),update_type:'note'});setAdminMsg(error?'Could not post update: '+error.message:'Timeline update posted.');if(!error)setActivity({title:'',description:''});setActionBusy(false)};
 const uploadFile=async e=>{e.preventDefault();if(!selected||!upload)return;setActionBusy(true);const safe=upload.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=selected.id+'/'+Date.now()+'-'+safe;const {error:upErr}=await db.storage.from('client-project-files').upload(path,upload,{contentType:upload.type||'application/octet-stream',upsert:false});if(upErr)setAdminMsg('Upload failed: '+upErr.message);else{const {error}=await db.from('client_project_files').insert({project_id:selected.id,title:upload.name,file_name:upload.name,file_path:path,content_type:upload.type,file_size:upload.size});setAdminMsg(error?'File uploaded but could not be added to the portal: '+error.message:'File shared with the client.');if(!error)setUpload(null)}setActionBusy(false)};
 const createApproval=async e=>{e.preventDefault();if(!selected)return;setActionBusy(true);const {error}=await db.from('client_project_approvals').insert({project_id:selected.id,title:approval.title.trim(),description:approval.description.trim()||null,file_id:approval.file_id||null});setAdminMsg(error?'Could not request approval: '+error.message:'Design approval request sent to client.');if(!error)setApproval({title:'',description:'',file_id:''});setActionBusy(false)};
 const createInvoice=async e=>{e.preventDefault();if(!selected)return;const amount=Number(invoiceDraft.amount);if(!Number.isFinite(amount)||amount<=0){setAdminMsg('Enter a valid invoice amount in EGP.');return}setActionBusy(true);const invoiceNumber='VX-'+Date.now().toString().slice(-9);const {error}=await db.from('client_project_invoices').insert({project_id:selected.id,invoice_number:invoiceNumber,title:invoiceDraft.title.trim()||'Project payment',description:invoiceDraft.description.trim()||null,total_amount:amount,currency:'EGP',due_date:invoiceDraft.due_date||null});setAdminMsg(error?'Could not create invoice: '+error.message:'Invoice '+invoiceNumber+' created and shared with the client.');if(!error){setInvoiceDraft({title:'50% upfront deposit',amount:'',description:'',due_date:''});const {data}=await db.from('client_project_invoices').select('*').eq('project_id',selected.id).order('created_at',{ascending:false});setProjectInvoices(data||[])}setActionBusy(false)};
 const reviewPayment=async(payment,status)=>{if(!selected)return;setActionBusy(true);const {error}=await db.rpc('review_client_project_payment',{p_payment_id:payment.id,p_status:status});if(error)setAdminMsg('Could not review payment: '+error.message);else{setAdminMsg(status==='approved'?'Payment approved and invoice marked paid.':'Payment rejected.');const [i,p]=await Promise.all([db.from('client_project_invoices').select('*').eq('project_id',selected.id).order('created_at',{ascending:false}),db.from('client_project_payments').select('*').eq('project_id',selected.id).order('created_at',{ascending:false})]);setProjectInvoices(i.data||[]);setProjectPayments(p.data||[])}setActionBusy(false)};
 const rows=[['starter','SAT Academy — Starter'],['professional','SAT Academy — Professional'],['elite','SAT Academy — Elite'],['basic_care','Basic Care'],['complete_care','Complete Care'],...Object.entries(proposalPackages).flatMap(([proposal,packages])=>packages.map(p=>['proposal_'+proposal+'_'+p.name.toLowerCase(),(concepts.find(c=>c.id===proposal)?.title||proposal)+' — '+p.name]))];
 const pricingGroups=[{id:'all',label:'All prices',count:rows.length},{id:'care',label:'Care plans',count:2},{id:'sat',label:'SAT Academy',count:3},...concepts.map(concept=>({id:concept.id,label:concept.title,count:(proposalPackages[concept.id]||[]).length}))];
 const visiblePriceRows=rows.filter(([key,label])=>{
  const groupMatch=pricingGroup==='all'||(pricingGroup==='care'&&(key==='basic_care'||key==='complete_care'))||(pricingGroup==='sat'&&['starter','professional','elite'].includes(key))||(key.startsWith('proposal_'+pricingGroup+'_'));
  return groupMatch&&label.toLowerCase().includes(pricingSearch.trim().toLowerCase());
 });
 const changedPriceCount=rows.filter(([key])=>String(draft[key]?.amount??'')!==String(prices[key]?.amount??defaultPrices[key]?.amount??'')||String(draft[key]?.billing_note??'')!==String(prices[key]?.billing_note??defaultPrices[key]?.billing_note??'')).length;
